package com.enfec.one.asset.workflow;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="maintenance_tickets") public class MaintenanceTicket { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="request_id") private UUID requestId; @Column(name="asset_id",nullable=false) private UUID assetId; @Column(name="reported_by",nullable=false,length=100) private String reportedBy; @Column(name="issue_description",nullable=false,length=2000) private String issueDescription; @Column(length=2000) private String diagnosis; @Column(name="repairable") private Boolean repairable; @Column(length=2000) private String resolution; @Column(nullable=false,length=30) private String status="REPORTED"; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt; protected MaintenanceTicket(){} public MaintenanceTicket(UUID a,String u,String i){assetId=a;reportedBy=u;issueDescription=i;createdAt=OffsetDateTime.now(ZoneOffset.UTC);updatedAt=createdAt;} public void setRequestId(UUID id){requestId=id;} public void diagnose(String d,boolean r){diagnosis=d;repairable=r;status=r?"REPAIR":"REPLACEMENT";touch();} public void resolve(String r){resolution=r;status="RESOLVED";touch();} private void touch(){updatedAt=OffsetDateTime.now(ZoneOffset.UTC);} public UUID getId(){return id;} public UUID getRequestId(){return requestId;} public UUID getAssetId(){return assetId;} public String getReportedBy(){return reportedBy;} public String getIssueDescription(){return issueDescription;} public String getDiagnosis(){return diagnosis;} public Boolean getRepairable(){return repairable;} public String getResolution(){return resolution;} public String getStatus(){return status;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getUpdatedAt(){return updatedAt;} }
